import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

import { addNotice, addStudy, uploadPDF } from "../../services/api";

const AdminDashboard = () => {
  const navigate = useNavigate();

  const [noticeTitle, setNoticeTitle] = useState("");
  const [noticeContent, setNoticeContent] = useState("");

  const [studyTitle, setStudyTitle] = useState("");
  const [studySubject, setStudySubject] = useState("");
  const [studyContent, setStudyContent] = useState("");

  const [file, setFile] = useState(null);

  return (
    <div style={styles.container}>

      {/* 🟢 SIDEBAR */}
      <div style={styles.sidebar}>
        <h2 style={styles.logo}>EduSaarthi</h2>

        <button style={styles.sideBtn} onClick={() => navigate("/admin")}>
          🏠 Dashboard
        </button>

        <button style={styles.sideBtn} onClick={() => navigate("/chatbot")}>
          🤖 Chatbot
        </button>

        <button style={styles.sideBtn}>
          📢 Notices
        </button>

        <button style={styles.sideBtn}>
          📚 Study
        </button>

        <button style={styles.sideBtn}>
          📁 Upload
        </button>
      </div>

      {/* 🟢 MAIN CONTENT */}
      <div style={styles.main}>

        <h1 style={styles.title}>Admin Dashboard</h1>

        {/* 📢 NOTICES */}
        <div style={styles.card}>
          <h2>Notices</h2>

          <input
            placeholder="Title"
            value={noticeTitle}
            onChange={(e) => setNoticeTitle(e.target.value)}
            style={styles.input}
          />

          <input
            placeholder="Content"
            value={noticeContent}
            onChange={(e) => setNoticeContent(e.target.value)}
            style={styles.input}
          />

          <button
            style={styles.button}
            onClick={() =>
              addNotice({ title: noticeTitle, content: noticeContent }, "token")
            }
          >
            Add Notice
          </button>
        </div>

        {/* 📚 STUDY */}
        <div style={styles.card}>
          <h2>Study Material</h2>

          <input
            placeholder="Title"
            value={studyTitle}
            onChange={(e) => setStudyTitle(e.target.value)}
            style={styles.input}
          />

          <input
            placeholder="Subject"
            value={studySubject}
            onChange={(e) => setStudySubject(e.target.value)}
            style={styles.input}
          />

          <input
            placeholder="Content"
            value={studyContent}
            onChange={(e) => setStudyContent(e.target.value)}
            style={styles.input}
          />

          <button
            style={styles.button}
            onClick={() =>
              addStudy(
                {
                  title: studyTitle,
                  subject: studySubject,
                  content: studyContent,
                },
                "token"
              )
            }
          >
            Add Study
          </button>
        </div>

        {/* 📁 UPLOAD */}
        <div style={styles.card}>
          <h2>Upload PDF</h2>

          <input
            type="file"
            onChange={(e) => setFile(e.target.files[0])}
          />

          <button
            style={styles.button}
            onClick={() => uploadPDF(file, "token")}
          >
            Upload PDF
          </button>
        </div>

      </div>
    </div>
  );
};

export default AdminDashboard;

/* 🎨 STYLES */
const styles = {
  container: {
    display: "flex",
    height: "100vh",
    fontFamily: "Arial",
    background: "#0f172a",
    color: "white",
  },

  sidebar: {
    width: "220px",
    background: "#111827",
    padding: "20px",
    display: "flex",
    flexDirection: "column",
    gap: "10px",
  },

  logo: {
    marginBottom: "20px",
    color: "#38bdf8",
  },

  sideBtn: {
    padding: "10px",
    background: "#1f2937",
    color: "white",
    border: "none",
    cursor: "pointer",
    borderRadius: "6px",
  },

  main: {
    flex: 1,
    padding: "20px",
    overflowY: "auto",
  },

  title: {
    marginBottom: "20px",
  },

  card: {
    background: "#1e293b",
    padding: "20px",
    borderRadius: "10px",
    marginBottom: "20px",
  },

  input: {
    width: "100%",
    padding: "10px",
    margin: "5px 0",
    borderRadius: "5px",
    border: "none",
  },

  button: {
    marginTop: "10px",
    padding: "10px",
    background: "#38bdf8",
    border: "none",
    cursor: "pointer",
    borderRadius: "5px",
    color: "black",
    fontWeight: "bold",
  },
};
